const StaffVersionPolicy=(()=>{
 const versions=['常规版','24版','22版','22版2D','老汉艺版本'];
 function iso(y,m,d){const date=new Date(Date.UTC(y,m-1,d));return date.getUTCFullYear()===y&&date.getUTCMonth()+1===m&&date.getUTCDate()===d?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:''}
 function range(value){if(value===undefined||value===null||String(value).trim()==='')return null;let s=String(value).trim();if(/^\d{5}(?:\.\d+)?$/.test(s)){const date=new Date(Date.UTC(1899,11,30)+Math.floor(Number(s))*86400000);s=iso(date.getUTCFullYear(),date.getUTCMonth()+1,date.getUTCDate())}const m=s.match(/^(\d{4})[-/.年](\d{1,2})(?:[-/.月](\d{1,2})日?)?(?:[ T]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/);if(!m)return null;const y=Number(m[1]),month=Number(m[2]),day=m[3]?Number(m[3]):1,start=iso(y,month,day);if(!start)return null;if(m[3])return {start,end:start,precision:'day'};const last=new Date(Date.UTC(y,month,0)).getUTCDate();return {start,end:iso(y,month,last),precision:'month'}}
 function date(v){const r=range(v);return r?.precision==='day'?r.start:''}
 function validate(p){if(!p||!versions.includes(p.oldVersion)||!versions.includes(p.newVersion))return '请选择旧版和新版绩效';if(!date(p.oldBefore)||!date(p.newFrom))return '请填写包含年份的完整旧版截止日期和新版生效日期';if(date(p.oldBefore)>date(p.newFrom))return '旧版截止日期不能晚于新版生效日期，避免两个版本重叠';return ''}
 function resolve(name,signDate,staff={},rules={}){const p=rules[name];if(!p)return {version:staff[name]||'常规版',configured:false,reason:'固定版本'};const error=validate(p);if(error)return {version:p.newVersion||staff[name]||'常规版',configured:true,issue:'员工签约日期规则不完整：'+error};const r=range(signDate);if(!r)return {version:p.newVersion,configured:true,issue:'缺少或无法识别学生签约日期，请补充后重新匹配'};const before=date(p.oldBefore),from=date(p.newFrom);if(r.end<before)return {version:p.oldVersion,configured:true,reason:`签约${r.start}，早于${before}，执行旧版${p.oldVersion}`};if(r.start>=from)return {version:p.newVersion,configured:true,reason:`签约${r.start}，自${from}起执行新版${p.newVersion}`};return {version:p.newVersion,configured:true,issue:r.precision==='month'?'签约日期仅精确到月且跨越版本边界，请补充完整日期':'学生签约日期位于两个版本未覆盖的区间，请由经办人确认版本'} }
 function summary(p){return p?`${p.oldVersion}：签约 < ${p.oldBefore}；${p.newVersion}：签约 ≥ ${p.newFrom}`:'固定版本（无签约日期切换）'}
 return {versions,date,range,validate,resolve,summary};
})();
